import { http, HttpResponse } from "msw/http"
import { describe, expect, it } from "vitest"

import { siteConfig } from "@/config/site.config"

import { login } from "@/features/auth/api/login.api"
import { register } from "@/features/auth/api/register.api"
import { LOGIN_PATH, REGISTER_PATH } from "@/features/auth/constants/auth.constants"
import { server } from "@/test/server"

const LOGIN_URL = `${siteConfig.apiUrl}${LOGIN_PATH}`
const REGISTER_URL = `${siteConfig.apiUrl}${REGISTER_PATH}`

/** The user as DummyJSON's sign-in sends it, tokens included. */
const emily = {
  id: 1,
  username: "emilys",
  email: "emily.johnson@x.dummyjson.com",
  firstName: "Emily",
  lastName: "Johnson",
  gender: "female",
  image: "https://dummyjson.com/icon/emilys/128"
}

describe("login", () => {
  it("posts the credentials and keeps the user without the tokens", async () => {
    let body: unknown
    server.use(
      http.post(LOGIN_URL, async ({ request }) => {
        body = await request.json()
        return HttpResponse.json({
          ...emily,
          accessToken: "access-token-xyzzy",
          refreshToken: "refresh-token-plugh"
        })
      })
    )

    const user = await login({ username: "emilys", password: "emilyspass" })

    expect(body).toEqual({ username: "emilys", password: "emilyspass" })
    expect(user).toEqual({
      id: 1,
      username: "emilys",
      email: "emily.johnson@x.dummyjson.com",
      firstName: "Emily",
      lastName: "Johnson",
      image: "https://dummyjson.com/icon/emilys/128"
    })
    expect(JSON.stringify(user)).not.toMatch(/xyzzy|plugh/)
  })

  it("fails with the API's status for wrong credentials", async () => {
    server.use(
      http.post(LOGIN_URL, () =>
        HttpResponse.json({ message: "Invalid credentials" }, { status: 400 })
      )
    )

    await expect(login({ username: "emilys", password: "nope" })).rejects.toMatchObject({
      kind: "http",
      status: 400
    })
  })
})

describe("register", () => {
  it("sends the password once, without the confirmation, and drops its echo", async () => {
    let body: unknown
    server.use(
      http.post(REGISTER_URL, async ({ request }) => {
        body = await request.json()
        // DummyJSON echoes what it was sent, the password too.
        return HttpResponse.json({ ...Object(body), id: 209, role: "user" }, { status: 201 })
      })
    )

    const created = await register({
      firstName: "Ada",
      lastName: "Lovelace",
      username: "ada.lovelace",
      email: "ada@example.com",
      password: "velvet-river-compass-7",
      confirmPassword: "velvet-river-compass-7"
    })

    expect(body).toEqual({
      firstName: "Ada",
      lastName: "Lovelace",
      username: "ada.lovelace",
      email: "ada@example.com",
      password: "velvet-river-compass-7"
    })
    expect(created).toEqual({
      id: 209,
      firstName: "Ada",
      lastName: "Lovelace",
      username: "ada.lovelace",
      email: "ada@example.com"
    })
  })
})

import type { SessionUser } from "@/features/auth/schemas/auth.schema"

/**
 * No request yet: DummyJSON's `/auth/me` needs the token this module never keeps, so a reload
 * starts signed out. With your API, ask it who the cookie belongs to:
 * `api.get("/auth/me", { schema: sessionUserSchema })`, and answer `null` on a 401.
 */
export async function getSession(): Promise<SessionUser | null> {
  return null
}

import { api } from "@/lib/api"

import { LOGIN_PATH } from "@/features/auth/constants/auth.constants"
import { sessionUserSchema } from "@/features/auth/schemas/auth.schema"
import type { LoginFormInput, SessionUser } from "@/features/auth/schemas/auth.schema"

/** The schema keeps the user and drops the tokens DummyJSON sends with it. */
export function login(input: LoginFormInput, signal?: AbortSignal): Promise<SessionUser> {
  return api.post(LOGIN_PATH, input, { schema: sessionUserSchema, signal })
}

/** No request yet: with your API, a request that ends the session and clears its cookie. */
export async function logout(): Promise<null> {
  return null
}

export const authKeys = {
  session: ["auth", "session"] as const
}

import { api } from "@/lib/api"

import { REGISTER_PATH } from "@/features/auth/constants/auth.constants"
import { registeredUserSchema } from "@/features/auth/schemas/auth.schema"
import type { RegisteredUser, RegisterFormInput } from "@/features/auth/schemas/auth.schema"

/**
 * Sends the password once, for your server to hash; the confirmation stays in the form. The
 * schema drops the password DummyJSON echoes back.
 */
export function register(input: RegisterFormInput, signal?: AbortSignal): Promise<RegisteredUser> {
  const { firstName, lastName, username, email, password } = input
  return api.post(
    REGISTER_PATH,
    { firstName, lastName, username, email, password },
    { schema: registeredUserSchema, signal }
  )
}

import { queryOptions } from "@tanstack/react-query"

import { getSession } from "@/features/auth/api/get-session.api"
import { authKeys } from "@/features/auth/api/query-keys"

/**
 * The signed-in user lives only in this cache, in memory: nothing goes to `localStorage` or a
 * cookie from the browser. Wire your real session in `getSession` and in the `api` instance's
 * `getHeaders` or `credentials`, and guard your private pages in your own routes or proxy.
 */
export const sessionQueryOptions = queryOptions({
  queryKey: authKeys.session,
  queryFn: getSession,
  // Only sign-in and sign-out change it: no refetch of the placeholder `getSession`, which answers
  // `null`, may sign the visitor out. With a real `getSession`, remove this line.
  staleTime: Infinity,
  // Kept while no page shows it, until a reload: the default would drop it five minutes after the
  // visitor leaves the sign-in page.
  gcTime: Infinity
})

import type { ComponentProps } from "react"

import { Link } from "@tanstack/react-router"

type AuthLinkProps = Omit<ComponentProps<typeof Link>, "to" | "params" | "search"> & {
  href: string
}

/**
 * The router's link, so moving between the forms stays a client navigation. The path is a plain
 * string, so it type-checks before the pages it points at are in the route tree.
 */
export function AuthLink({ href, ...props }: AuthLinkProps) {
  const to: string = href
  return <Link to={to} {...props} />
}

import { screen, within } from "@testing-library/react"
import userEvent from "@testing-library/user-event"
import type { UserEvent } from "@testing-library/user-event"
import { http, HttpResponse } from "msw/http"
import { describe, expect, it } from "vitest"

import { siteConfig } from "@/config/site.config"

import { LoginForm } from "@/features/auth/components/LoginForm"
import { LOGIN_PATH } from "@/features/auth/constants/auth.constants"
import { renderWithProviders } from "@/test/render"
import { server } from "@/test/server"

const LOGIN_URL = `${siteConfig.apiUrl}${LOGIN_PATH}`
// `LoginForm` has links, so it renders inside a route.
const LOGIN_PAGE = { path: "/login" }

const emily = {
  id: 1,
  username: "emilys",
  email: "emily.johnson@x.dummyjson.com",
  firstName: "Emily",
  lastName: "Johnson",
  image: "https://dummyjson.com/icon/emilys/128",
  accessToken: "access-token-xyzzy",
  refreshToken: "refresh-token-plugh"
}

/** DummyJSON's sign-in: its first user's credentials work, anything else answers 400. */
function serveLogin() {
  const bodies: unknown[] = []
  server.use(
    http.post(LOGIN_URL, async ({ request }) => {
      const body = (await request.json()) as { username: string; password: string }
      bodies.push(body)
      return body.username === "emilys" && body.password === "emilyspass"
        ? HttpResponse.json(emily)
        : HttpResponse.json({ message: "Invalid credentials" }, { status: 400 })
    })
  )
  return bodies
}

async function renderLogin() {
  renderWithProviders(<LoginForm />, { route: LOGIN_PAGE })
  return screen.findByLabelText("Username")
}

async function signIn(user: UserEvent, username: string, password: string) {
  await user.type(await renderLogin(), username)
  await user.type(screen.getByLabelText("Password"), password)
  await user.click(screen.getByRole("button", { name: "Sign in" }))
}

describe("LoginForm", () => {
  it("sends nothing while a field is empty", async () => {
    const bodies = serveLogin()
    const user = userEvent.setup()
    await renderLogin()

    await user.click(screen.getByRole("button", { name: "Sign in" }))

    expect(await screen.findByText("Enter your username")).toBeInTheDocument()
    expect(screen.getByText("Enter your password")).toBeInTheDocument()
    expect(screen.getByLabelText("Username")).toHaveAttribute("aria-invalid", "true")
    expect(bodies).toHaveLength(0)
  })

  it("is a post form whose password field a password manager recognizes", async () => {
    await renderLogin()

    const password = screen.getByLabelText("Password")
    expect(password).toHaveAttribute("type", "password")
    expect(password).toHaveAttribute("autocomplete", "current-password")
    expect(password.closest("form")).toHaveAttribute("method", "post")
  })

  it("shows and hides the password", async () => {
    const user = userEvent.setup()
    await renderLogin()
    const password = screen.getByLabelText("Password")
    const toggle = screen.getByRole("button", { name: "Show password" })

    await user.click(toggle)
    expect(password).toHaveAttribute("type", "text")
    expect(toggle).toHaveAttribute("aria-pressed", "true")

    await user.click(toggle)
    expect(password).toHaveAttribute("type", "password")
  })

  it("says the credentials are wrong and clears the password", async () => {
    serveLogin()
    const user = userEvent.setup()

    await signIn(user, "emilys", "wrong-password-quux")

    expect(await screen.findByRole("alert")).toHaveTextContent("Wrong username or password")
    expect(screen.getByLabelText("Username")).toHaveValue("emilys")
    expect(screen.getByLabelText("Password")).toHaveValue("")
    expect(screen.getByLabelText("Password")).toHaveFocus()
  })

  it("says so when the request fails for another reason", async () => {
    server.use(http.post(LOGIN_URL, () => HttpResponse.json({}, { status: 500 })))
    const user = userEvent.setup()

    await signIn(user, "emilys", "emilyspass")

    expect(await screen.findByRole("alert")).toHaveTextContent("Could not sign in")
  })

  it("fills in the demo account, signs in and shows who is signed in, without the tokens", async () => {
    const bodies = serveLogin()
    const user = userEvent.setup()
    await renderLogin()

    await user.click(screen.getByRole("button", { name: "Use demo account" }))
    await user.click(screen.getByRole("button", { name: "Sign in" }))

    const status = await screen.findByRole("status")
    expect(status).toHaveTextContent("Emily Johnson")
    expect(status).toHaveTextContent("@emilys")
    expect(bodies).toEqual([{ username: "emilys", password: "emilyspass" }])
    expect(document.body.innerHTML).not.toMatch(/xyzzy|plugh|emilyspass/)
  })

  it("signs out back to the form", async () => {
    serveLogin()
    const user = userEvent.setup()

    await signIn(user, "emilys", "emilyspass")
    await user.click(await screen.findByRole("button", { name: "Sign out" }))

    expect(await screen.findByLabelText("Username")).toHaveValue("")
    expect(screen.queryByRole("status")).not.toBeInTheDocument()
  })

  it("links to the sign-up page", async () => {
    await renderLogin()

    const prompt = screen.getByText(/No account yet/)
    expect(within(prompt).getByRole("link", { name: "Create one" })).toHaveAttribute(
      "href",
      "/register"
    )
  })
})

"use client"

import { EyeIcon, EyeOffIcon } from "lucide-react"
import { zodResolver } from "@hookform/resolvers/zod"
import { useViraPassword } from "@virastack/password"
import { useForm, useWatch } from "react-hook-form"

import { Button } from "@/components/ui/button"
import { Field, FieldError, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { AuthLink } from "@/features/auth/components/AuthLink"
import { PasswordInput } from "@/features/auth/components/PasswordInput"
import { SignedInCard } from "@/features/auth/components/SignedInCard"
import { DEMO_ACCOUNT, REGISTER_ROUTE } from "@/features/auth/constants/auth.constants"
import { isInvalidCredentials } from "@/features/auth/helpers/is-invalid-credentials"
import { useLogin } from "@/features/auth/hooks/use-login"
import { useSession } from "@/features/auth/hooks/use-session"
import { loginFormSchema } from "@/features/auth/schemas/auth.schema"
import type { LoginFormInput } from "@/features/auth/schemas/auth.schema"

export function LoginForm() {
  const session = useSession()
  const login = useLogin()
  const form = useForm<LoginFormInput>({
    resolver: zodResolver(loginFormSchema),
    defaultValues: { username: "", password: "" }
  })
  const { errors, isSubmitting } = form.formState
  // From `useWatch`, so `setValue` and `reset` reach the hook too.
  const passwordValue = useWatch({ control: form.control, name: "password" })
  // No policy: signing in checks the password, it does not judge it.
  const password = useViraPassword({
    id: "password",
    value: passwordValue,
    icons: { show: <EyeIcon aria-hidden />, hide: <EyeOffIcon aria-hidden /> },
    btnProps: { "aria-label": "Show password" },
    inputProps: {
      "aria-invalid": Boolean(errors.password),
      ...(errors.password && { "aria-describedby": "password-error" })
    }
  })

  const onSubmit = form.handleSubmit(async (input) => {
    try {
      await login.mutateAsync(input)
      // The form stays mounted under the signed-in card, so the password leaves it now.
      form.reset()
    } catch (error) {
      form.setValue("password", "")
      form.setError("root.server", {
        message: isInvalidCredentials(error)
          ? "Wrong username or password"
          : "Could not sign in. Try again."
      })
      form.setFocus("password")
    } finally {
      // The mutation's variables hold the password: drop them once the answer is in.
      login.reset()
    }
  })

  // The form shows until the session says someone is signed in, so the server renders it too and
  // it works before hydration.
  if (session.data) return <SignedInCard user={session.data} />

  return (
    <div className="flex flex-col gap-6">
      <div className="flex flex-wrap items-center justify-between gap-2 rounded-lg border border-dashed p-3 text-sm">
        <p className="text-muted-foreground">
          Demo account: <span className="font-mono text-foreground">{DEMO_ACCOUNT.username}</span> /{" "}
          <span className="font-mono text-foreground">{DEMO_ACCOUNT.password}</span>
        </p>
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={() => {
            form.clearErrors()
            form.setValue("username", DEMO_ACCOUNT.username)
            form.setValue("password", DEMO_ACCOUNT.password)
          }}
        >
          Use demo account
        </Button>
      </div>
      {/* `post`: before hydration the browser submits natively, and a GET puts the password in the URL. */}
      <form method="post" onSubmit={onSubmit} noValidate className="flex flex-col gap-4">
        <Field data-invalid={Boolean(errors.username)}>
          <FieldLabel htmlFor="username">Username</FieldLabel>
          <Input
            {...form.register("username")}
            id="username"
            autoComplete="username"
            autoCapitalize="none"
            spellCheck={false}
            aria-invalid={Boolean(errors.username)}
            aria-describedby={errors.username ? "username-error" : undefined}
          />
          {errors.username ? (
            <FieldError id="username-error">{errors.username.message}</FieldError>
          ) : null}
        </Field>
        <Field data-invalid={Boolean(errors.password)}>
          <FieldLabel htmlFor="password">Password</FieldLabel>
          <PasswordInput
            {...form.register("password")}
            password={password}
            capsLockHint="Caps Lock is on"
          />
          {errors.password ? (
            <FieldError id="password-error">{errors.password.message}</FieldError>
          ) : null}
        </Field>
        {errors.root?.server ? (
          <p role="alert" className="text-sm text-destructive">
            {errors.root.server.message}
          </p>
        ) : null}
        <Button type="submit" disabled={isSubmitting}>
          {isSubmitting ? "Signing in…" : "Sign in"}
        </Button>
      </form>
      <p className="text-center text-sm text-muted-foreground">
        No account yet?{" "}
        <AuthLink
          href={REGISTER_ROUTE}
          className="font-medium text-foreground underline underline-offset-4"
        >
          Create one
        </AuthLink>
      </p>
    </div>
  )
}

"use client"

import type { ComponentProps } from "react"

import type { UseViraPasswordResult } from "@virastack/password"
import { cn } from "cn"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"

type PasswordInputProps = ComponentProps<typeof Input> & {
  /** What `useViraPassword` returns for this field: its input props and its toggle. */
  password: UseViraPasswordResult
  capsLockHint: string
}

/** shadcn's input with the hook's show and hide button inside it. */
export function PasswordInput({ password, capsLockHint, className, ...props }: PasswordInputProps) {
  const { children, ...toggle } = password.btnProps

  return (
    <>
      <div className="relative">
        {/* The hook's props hold attributes only, so `register()` keeps its ref and handlers. */}
        <Input {...password.inputProps} {...props} className={cn("pr-10", className)} />
        <Button
          variant="ghost"
          size="icon"
          {...toggle}
          className="absolute top-0 right-0 text-muted-foreground hover:bg-transparent"
        >
          {children}
        </Button>
      </div>
      {password.capsLock ? <p className="text-xs text-muted-foreground">{capsLockHint}</p> : null}
    </>
  )
}

"use client"

import { CheckIcon, XIcon } from "lucide-react"
import type { UseViraPasswordResult } from "@virastack/password"
import type { PasswordChecks } from "@virastack/password/strength"
import { cn } from "cn"

import { PASSWORD_POLICY } from "@/features/auth/constants/auth.constants"

const FILLED_BARS = { weak: 1, fair: 2, good: 3, strong: 4 } as const

const LEVELS = { weak: "Weak", fair: "Fair", good: "Good", strong: "Strong" } as const

const RULES: { label: string; isMet: (checks: PasswordChecks) => boolean }[] = [
  {
    label: `${PASSWORD_POLICY.minLength} to ${PASSWORD_POLICY.maxLength} characters`,
    isMet: (checks) => checks.minLength && checks.maxLength
  },
  { label: "Not a common password", isMet: (checks) => checks.notCommon },
  { label: "No repeats or sequences like aaaa or 1234", isMet: (checks) => checks.notRepetitive },
  { label: "Not your name, username or email", isMet: (checks) => checks.notPersonal }
]

type PasswordStrengthProps = Pick<UseViraPasswordResult, "strength" | "strengthProps">

/** The bar and the rules are the module's; the package only scores the password. */
export function PasswordStrength({ strength, strengthProps }: PasswordStrengthProps) {
  const typed = strength !== null && strength.length > 0
  const filled = typed ? FILLED_BARS[strength.level] : 0

  return (
    <div className="flex flex-col gap-2">
      <div aria-hidden className="grid grid-cols-4 gap-1">
        {[1, 2, 3, 4].map((bar) => (
          <span
            key={bar}
            className={cn(
              "h-1 rounded-full bg-muted transition-colors",
              bar <= filled && (strength?.valid ? "bg-primary" : "bg-destructive")
            )}
          />
        ))}
      </div>
      {/* A live region: it announces the level, not every rule, so typing stays quiet. */}
      <p {...strengthProps} className="text-xs text-muted-foreground">
        {typed
          ? `Strength: ${LEVELS[strength.level]}`
          : "Choose a long password you don't use elsewhere"}
      </p>
      <ul className="flex flex-col gap-1 text-xs">
        {RULES.map(({ label, isMet }) => {
          const met = typed && isMet(strength.checks)
          const Icon = met ? CheckIcon : XIcon

          return (
            <li
              key={label}
              className={cn(
                "flex items-center gap-1.5",
                met ? "text-foreground" : "text-muted-foreground"
              )}
            >
              <Icon aria-hidden className="size-3.5 shrink-0" />
              <span className="sr-only">{met ? "Met:" : "Not met:"} </span>
              {label}
            </li>
          )
        })}
      </ul>
    </div>
  )
}

import { screen } from "@testing-library/react"
import userEvent from "@testing-library/user-event"
import type { UserEvent } from "@testing-library/user-event"
import { http, HttpResponse } from "msw/http"
import { describe, expect, it } from "vitest"

import { siteConfig } from "@/config/site.config"

import { RegisterForm } from "@/features/auth/components/RegisterForm"
import { REGISTER_PATH } from "@/features/auth/constants/auth.constants"
import { renderWithProviders } from "@/test/render"
import { server } from "@/test/server"

const REGISTER_URL = `${siteConfig.apiUrl}${REGISTER_PATH}`
// `RegisterForm` has links, so it renders inside a route.
const REGISTER_PAGE = { path: "/register" }
const PASSWORD = "velvet-river-compass-7"

/** DummyJSON's `/users/add`: it echoes what it was sent, the password too, with a new id. */
function serveRegister() {
  const bodies: unknown[] = []
  server.use(
    http.post(REGISTER_URL, async ({ request }) => {
      const body: unknown = await request.json()
      bodies.push(body)
      return HttpResponse.json({ ...Object(body), id: 209 }, { status: 201 })
    })
  )
  return bodies
}

async function renderRegister() {
  renderWithProviders(<RegisterForm />, { route: REGISTER_PAGE })
  return screen.findByLabelText("First name")
}

async function fillDetails(user: UserEvent) {
  await user.type(screen.getByLabelText("First name"), "Ada")
  await user.type(screen.getByLabelText("Last name"), "Lovelace")
  await user.type(screen.getByLabelText("Username"), "ada.lovelace")
  await user.type(screen.getByLabelText("Email"), "ada@example.com")
}

async function fillAndSubmit(user: UserEvent, password = PASSWORD, confirm = password) {
  await fillDetails(user)
  await user.type(screen.getByLabelText("Password"), password)
  await user.type(screen.getByLabelText("Confirm password"), confirm)
  await user.click(screen.getByRole("button", { name: "Create account" }))
}

describe("RegisterForm", () => {
  it("shows every error and sends nothing while the input is invalid", async () => {
    const bodies = serveRegister()
    const user = userEvent.setup()
    await renderRegister()

    await user.type(screen.getByLabelText("Username"), "not valid")
    await user.type(screen.getByLabelText("Email"), "ada@")
    await user.click(screen.getByRole("button", { name: "Create account" }))

    expect(await screen.findByText("Enter your first name")).toBeInTheDocument()
    expect(screen.getByText("Enter your last name")).toBeInTheDocument()
    expect(screen.getByText(/Use letters, numbers/)).toBeInTheDocument()
    expect(screen.getByText("Enter a valid email address")).toBeInTheDocument()
    expect(screen.getByText("Use at least 15 characters")).toBeInTheDocument()
    // The error joins the strength in the field's description; it does not replace it.
    const password = screen.getByLabelText("Password")
    expect(password).toHaveAccessibleDescription(/Use at least 15 characters/)
    expect(password).toHaveAccessibleDescription(/Choose a long password/)
    expect(bodies).toHaveLength(0)
  })

  it("scores the password as it is typed and ticks the rules it meets", async () => {
    const user = userEvent.setup()
    await renderRegister()
    const password = screen.getByLabelText("Password")
    expect(password).toHaveAttribute("autocomplete", "new-password")

    await user.type(password, "short")
    expect(screen.getByText("Strength: Weak")).toHaveAttribute("role", "status")
    expect(screen.getByText("15 to 64 characters")).toHaveTextContent("Not met:")

    await user.clear(password)
    await user.type(password, PASSWORD)
    expect(screen.getByText("Strength: Good")).toBeInTheDocument()
    expect(screen.getByText("15 to 64 characters")).toHaveTextContent("Met:")
    expect(password).toHaveAccessibleDescription(/Strength: Good/)
  })

  it("turns down a common password, one made of the name, and a confirmation that differs", async () => {
    const bodies = serveRegister()
    const user = userEvent.setup()
    await renderRegister()

    await fillAndSubmit(user, "lovelace-lovelace-1815", "lovelace-lovelace-1816")
    expect(await screen.findByText("Don't use your name, username or email")).toBeInTheDocument()
    expect(screen.getByText("The passwords don't match")).toBeInTheDocument()

    await user.clear(screen.getByLabelText("Password"))
    await user.type(screen.getByLabelText("Password"), "password12345678")
    await user.click(screen.getByRole("button", { name: "Create account" }))
    expect(await screen.findByText("This password is too common")).toBeInTheDocument()
    expect(bodies).toHaveLength(0)
  })

  it("shows the returned account, says it was not saved, and keeps the password out of it", async () => {
    const bodies = serveRegister()
    const user = userEvent.setup()
    await renderRegister()

    await fillAndSubmit(user)

    const result = await screen.findByRole("status")
    expect(result).toHaveTextContent("user #209")
    expect(result).toHaveTextContent("Ada Lovelace")
    expect(result).toHaveTextContent("@ada.lovelace")
    expect(result).toHaveTextContent(/not saved/i)
    expect(screen.getByRole("link", { name: "Go to sign in" })).toHaveAttribute("href", "/login")
    expect(bodies).toEqual([
      {
        firstName: "Ada",
        lastName: "Lovelace",
        username: "ada.lovelace",
        email: "ada@example.com",
        password: PASSWORD
      }
    ])
    expect(document.body.innerHTML).not.toContain(PASSWORD)
  })

  it("starts over with an empty form", async () => {
    serveRegister()
